import static org.junit.jupiter.api.Assertions.*;
import java.util.List;
import org.junit.jupiter.api.Test;
import org.junit.jupiter.params.ParameterizedTest;
import org.junit.jupiter.params.provider.CsvSource;

class MathsTest {
    static int max(List<Integer> xs) {
        if (xs.isEmpty()) throw new IllegalArgumentException("empty");
        int best = xs.get(0);                         // not 0: handles negatives.
        for (int x : xs) if (x > best) best = x;
        return best;
    }

    @ParameterizedTest
    @CsvSource({"'5', 5", "'3 7 5', 7", "'-4 -2', -2", "'9 9', 9"})
    void findsLargest(String input, int expected) {
        List<Integer> xs = java.util.Arrays.stream(input.split(" ")).map(Integer::valueOf).toList();  // arrange.
        assertEquals(expected, max(xs));                                                          // act + assert.
    }

    @Test
    void rejectsEmpty() {
        var e = assertThrows(IllegalArgumentException.class, () -> max(List.of()));
        assertEquals("empty", e.getMessage());
    }
}
```

